android.extraProguardRules:
# === EveryBible P2 keep rules (reflection/JNI-based libs) ===

# react-native-reanimated
-keep class com.swmansion.reanimated.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }

# react-native-gesture-handler
-keep class com.swmansion.gesturehandler.** { *; }

# react-native-svg
-keep public class com.horcrux.svg.** { *; }

# react-native-mmkv
-keep class com.tencent.mmkv.** { *; }
-keep class com.reactnativemmkv.** { *; }
-dontwarn com.tencent.mmkv.**

# @shopify/flash-list
-keep class com.shopify.reactnative.flash_list.** { *; }

# react-native-screens
-keep class com.swmansion.rnscreens.** { *; }

# react-native-video-trim
-keep class com.reactnativevideotrim.** { *; }

# react-native-view-shot
-keep class fr.greweb.reactnativeviewshot.** { *; }

# @react-native-google-signin/google-signin (Google Play Services reflection)
-keep class com.google.android.gms.** { *; }
-dontwarn com.google.android.gms.**
-keep class com.google.android.libraries.** { *; }

# expo-av / ExoPlayer media playback
-keep class com.google.android.exoplayer2.** { *; }
-dontwarn com.google.android.exoplayer2.**

# expo-notifications
-keep class expo.modules.notifications.** { *; }

# @kesha-antonov/react-native-background-downloader
-keep class com.eko.** { *; }

# Hermes / React Native core JNI surfaces
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.react.turbomodule.core.** { *; }

# Expo modules core (autolinking + reflection)
-keep class expo.modules.** { *; }
-dontwarn expo.modules.**

# OkHttp / Okio (used by Supabase fetch + networking) — suppress optional-dependency warnings
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn org.conscrypt.**

# Keep annotations and signatures so reflection/generics survive
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
